import { z } from 'zod';
const cnicRegex = /^\d{5}-\d{7}-\d$/;
export const createCustomerSchema = z.object({
    name: z.string().min(2),
    cnic: z.string().regex(cnicRegex, 'CNIC format: XXXXX-XXXXXXX-X'),
    phone: z.string().min(10),
    fatherName: z.string().optional(),
    cnicExpiry: z.string().optional(),
    address: z.string().optional(),
    area: z.string().optional(),
    officeAddress: z.string().min(1, 'Office address is required'),
    salary: z.preprocess((v) => (v === '' || v === null || v === undefined || (typeof v === 'number' && isNaN(v))) ? undefined : Number(v), z.number({ required_error: 'Salary is required', invalid_type_error: 'Enter a valid salary amount' }).positive('Salary must be greater than 0')),
    occupation: z.string().optional(),
    employer: z.string().optional(),
    guarantorName: z.string().optional(),
    guarantorPhone: z.string().optional(),
    guarantorCnic: z.string().regex(cnicRegex, 'CNIC format: XXXXX-XXXXXXX-X').optional().or(z.literal('')),
    guarantorAddress: z.string().optional(),
    guarantorRelation: z.string().optional(),
    guarantor2Name: z.string().optional(),
    guarantor2Phone: z.string().optional(),
    guarantor2Cnic: z.string().regex(cnicRegex, 'CNIC format: XXXXX-XXXXXXX-X').optional().or(z.literal('')),
    guarantor2Address: z.string().optional(),
    guarantor2Relation: z.string().optional(),
    photoUrl: z.string().url('Customer photo is required'),
    cnicFrontUrl: z.string().url('CNIC front image is required'),
    cnicBackUrl: z.string().url('CNIC back image is required'),
    blankChequeUrl: z.string().url().optional(),
    guarantorCnicFrontUrl: z.string().url().optional(),
    guarantorCnicBackUrl: z.string().url().optional(),
    guarantor2CnicFrontUrl: z.string().url().optional(),
    guarantor2CnicBackUrl: z.string().url().optional(),
    cnicFrontHash: z.string().optional(),
    cnicBackHash: z.string().optional(),
    blankChequeHash: z.string().optional(),
    chequeBank: z.string().optional(),
    chequeAccountNo: z.string().optional(),
    chequeNo: z.string().optional(),
});
export const updateCustomerSchema = createCustomerSchema.partial().extend({
    cnic: z.string().regex(cnicRegex, 'Format: XXXXX-XXXXXXX-X').optional().or(z.literal('')),
});
